    private void chooseCopy(PhotoAdjustments settings)throws Exception{
        ui(()->invoke(panel,"chooseAdjustmentTargets",new Class<?>[]{PhotoAdjustments.class,DownloadedPhoto.class},settings,photos.get(0)));AlertDialog choose=(AlertDialog)get(panel,"adjustmentCopyDialog");
        ui(()->{choose.getButton(-3).performClick();choose.getButton(-1).performClick();});ui(()->{});AlertDialog confirm=(AlertDialog)get(panel,"adjustmentCopyDialog");check("copy-options-confirmation",confirm!=null&&confirm!=choose);capture("04-copy-options");layout(confirm);ui(()->confirm.getButton(-1).performClick());ui(()->{});
    }
    private void unavailableSavedVersion(PhotoAdjustments settings,PhotoEditStore.Draft before)throws Exception{
        PhotoEditStore.Draft unavailable=new PhotoEditStore.Draft(before.sourceSha,null,"",0,PhotoAdjustments.NONE.with(PhotoAdjustments.Parameter.CONTRAST,31),PhotoGeometry.NONE,PhotoBorder.NONE,false);
        String model=PhotoPresetRenderer.modelVersion(unavailable.profile());Method keyMethod=PhotoPresetBatch.class.getDeclaredMethod("key",String.class,String.class,String.class);keyMethod.setAccessible(true);String key=(String)keyMethod.invoke(null,before.sourceSha,unavailable.effectPresetSha(),model);check("saved-regression-own-key",key.matches("[a-f0-9]{64}"));
        File effectFile=new File(photos.get(1).file().getParentFile(),"effect-"+key+"__Effect.JPG");files.add(effectFile);new PhotoPresetRenderer(activity.getAssets()).render(photos.get(1).file(),effectFile,unavailable.profile(),()->false,null);
        File recordDir=new File(activity.getFilesDir(),"photo-preset-results");recordDir.mkdirs();for(String suffix:new String[]{".record",".model",".source",".meta"}){File file=new File(recordDir,key+suffix);files.add(file);files.add(new File(file.getPath()+".bak"));files.add(new File(file.getPath()+".new"));}
        try(DataOutputStream out=new DataOutputStream(new FileOutputStream(new File(recordDir,key+".record")))){out.writeInt(0x50424531);out.writeLong(effectFile.length());out.writeUTF(sha(effectFile));}
        Constructor<DownloadedPhoto> photo=DownloadedPhoto.class.getDeclaredConstructor(File.class,String.class);photo.setAccessible(true);DownloadedPhoto effect=photo.newInstance(effectFile,"HISTORICAL_SAVED.JPG");
        Class<?> sourceClass=Class.forName("cc.huevia.album.PhotoPresetSources",true,getTargetContext().getClassLoader());Constructor<?> constructor=sourceClass.getDeclaredConstructor(File.class,File.class);constructor.setAccessible(true);Object sources=constructor.newInstance(activity.getFilesDir(),activity.getExternalFilesDir(Environment.DIRECTORY_PICTURES));Method remember=sourceClass.getDeclaredMethod("rememberModel",String.class,String.class);remember.setAccessible(true);remember.invoke(sources,key,model);
        Method bind=sourceClass.getDeclaredMethod("bind",DownloadedPhoto.class,DownloadedPhoto.class,String.class,String.class,String.class,java.util.function.BooleanSupplier.class);bind.setAccessible(true);bind.invoke(sources,effect,photos.get(1),unavailable.effectPresetSha(),"Historical fixture",model,(java.util.function.BooleanSupplier)()->false);
        PhotoPresetBatch batch=(PhotoPresetBatch)get(panel,"photoPresets");PhotoSavedVersion resolved=PhotoSavedVersion.resolve(batch,effect);check("historical-effect-resolves-real-original",!resolved.unrecoverable&&resolved.photo.file().getCanonicalFile().equals(photos.get(1).file().getCanonicalFile()));
        PhotoEditStore.Draft retained=new PhotoEditStore.Draft(before.sourceSha,before.presetBytes(),before.name,before.strength,before.adjustments,before.geometry,before.border,true);store.save(retained);check("historical-parameters-unavailable",!PhotoPresetBatch.matchesSavedDraft(effect,retained));
        ui(()->panel.openLocalWorkspace(Arrays.asList(photos.get(0),effect,photos.get(2)),0));until(()->editor.isReady(),"editor-reopened-for-saved-regression");
        ui(()->invoke(panel,"chooseAdjustmentTargets",new Class<?>[]{PhotoAdjustments.class,DownloadedPhoto.class},settings,photos.get(0)));AlertDialog choose=(AlertDialog)get(panel,"adjustmentCopyDialog");ui(()->{choose.getButton(-3).performClick();choose.getButton(-1).performClick();});ui(()->{});AlertDialog confirm=(AlertDialog)get(panel,"adjustmentCopyDialog");ui(()->confirm.getButton(-1).performClick());ui(()->{});until(()->!(Boolean)get(panel,"preparingEditedExport"),"saved-regression-preflight-finished");
        check("unavailable-saved-version-zero-target-writes",store.read(before.sourceSha).identity().equals(retained.identity())&&store.read(before.sourceSha).exported&&store.read(hashes.get(2))==null);check("unavailable-saved-version-no-receipt",get(panel,"adjustmentCopyReceipt")==null);capture("05-unavailable-saved-version");
    }
    private DownloadedPhoto fixture(int index)throws Exception{
        int id=getTargetContext().getResources().getIdentifier("preset_template","drawable","cc.huevia");Bitmap sample=BitmapFactory.decodeResource(getTargetContext().getResources(),id);check("shipping-photo-fixture",sample!=null);Bitmap image=Bitmap.createScaledBitmap(sample,1200,800,true);if(image!=sample)sample.recycle();if(!image.isMutable()){Bitmap mutable=image.copy(Bitmap.Config.ARGB_8888,true);image.recycle();image=mutable;}if(index>0){Canvas canvas=new Canvas(image);Paint p=new Paint();p.setColor(index==1?0x33a87f42:0x3365a9cd);canvas.drawRect(0,0,1200,800,p);}
        File folder=new File(getTargetContext().getExternalFilesDir(Environment.DIRECTORY_PICTURES),"camera-album");folder.mkdirs();File file=new File(folder,"colour-qa-"+args.getString("runId")+"-"+index+"__PHOTO.JPG");try(FileOutputStream out=new FileOutputStream(file)){image.compress(Bitmap.CompressFormat.JPEG,98,out);}image.recycle();android.media.ExifInterface exif=new android.media.ExifInterface(file.getPath());exif.setAttribute("Orientation","1");exif.setAttribute("ImageDescription","Own colour QA fixture "+UUID.randomUUID());exif.saveAttributes();files.add(file);hashes.add(sha(file));Constructor<DownloadedPhoto> c=DownloadedPhoto.class.getDeclaredConstructor(File.class,String.class);c.setAccessible(true);return c.newInstance(file,"DSC_COLOUR_"+index+".JPG");
    }
    private void setCurveGesture(View graph){long time=SystemClock.uptimeMillis();float x=graph.getWidth()*.5f,y=graph.getHeight()*.32f;graph.dispatchTouchEvent(MotionEvent.obtain(time,time,MotionEvent.ACTION_DOWN,x,y,0));graph.dispatchTouchEvent(MotionEvent.obtain(time,time+30,MotionEvent.ACTION_MOVE,x,y,0));graph.dispatchTouchEvent(MotionEvent.obtain(time,time+60,MotionEvent.ACTION_UP,x,y,0));}
    private PhotoColorDialog colour()throws Exception{return (PhotoColorDialog)get(editor,"popup");}
    private PhotoAdjustments manual()throws Exception{return (PhotoAdjustments)get(editor,"adjustments");}
    private String identity()throws Exception{return manual().identity();}
    private void trackDraft(String sha)throws Exception{Field f=PhotoEditStore.class.getDeclaredField("root");f.setAccessible(true);draftFiles.add(new File((File)f.get(store),sha+".draft"));}
    private void drain()throws Exception{if(editor==null)return;CountDownLatch latch=new CountDownLatch(1);ui(()->editor.afterPendingSaves(latch::countDown));check("pending-saves-drained",latch.await(10,TimeUnit.SECONDS));}
    private void waitEditor()throws Exception{until(()->{ThreadPoolExecutor p=(ThreadPoolExecutor)get(editor,"previews");return p.getActiveCount()==0&&p.getQueue().isEmpty();},"editor-preview-ready");ui(()->{});}
    private void capture(String name)throws Exception{android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow(),guide=root==null?null:findGuide(root);if(guide!=null){guide.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);SystemClock.sleep(350);}SystemClock.sleep(250);ui(()->{});Bitmap screen=getUiAutomation().takeScreenshot();check("screenshot-"+name,screen!=null);try(FileOutputStream out=new FileOutputStream(new File(output,name+".png"))){screen.compress(Bitmap.CompressFormat.PNG,100,out);}screen.recycle();}
    private android.view.accessibility.AccessibilityNodeInfo findGuide(android.view.accessibility.AccessibilityNodeInfo node){if(node.getText()!=null&&node.getText().toString().equalsIgnoreCase("Got it"))return node;for(int i=0;i<node.getChildCount();i++){android.view.accessibility.AccessibilityNodeInfo child=node.getChild(i);if(child!=null){android.view.accessibility.AccessibilityNodeInfo found=findGuide(child);if(found!=null)return found;}}return null;}
    private void layout(Dialog dialog)throws Exception{ui(()->{View root=dialog.getWindow().getDecorView();check("dialog-visible",root.getWidth()>0&&root.getHeight()>0);View action=root.findViewWithTag("colour-apply");if(action==null&&dialog instanceof AlertDialog)action=((AlertDialog)dialog).getButton(-1);Rect rect=new Rect();check("primary-action-visible",action!=null&&action.getGlobalVisibleRect(rect)&&rect.height()>=40*activity.getResources().getDisplayMetrics().density);});}
    private EditText findInput(View view){if(view instanceof EditText)return (EditText)view;if(view instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)view).getChildCount();i++){EditText value=findInput(((android.view.ViewGroup)view).getChildAt(i));if(value!=null)return value;}return null;}
    private interface Checked{void run()throws Exception;}private interface Check{boolean test()throws Exception;}
    private void ui(Checked work){Throwable[] failure={null};runOnMainSync(()->{try{work.run();}catch(Throwable e){failure[0]=e;}});if(failure[0]!=null)throw new RuntimeException(failure[0]);}
    private void until(Check work,String name)throws Exception{long end=SystemClock.uptimeMillis()+15000;while(SystemClock.uptimeMillis()<end){boolean[] ready={false};ui(()->ready[0]=work.test());if(ready[0]){check(name,true);return;}SystemClock.sleep(40);}check(name,false);}
    private void check(String name,boolean value){if(!value)throw new AssertionError(name);checks.put(name);}
    private static Object get(Object value,String name)throws Exception{Field field=value.getClass().getDeclaredField(name);field.setAccessible(true);return field.get(value);}
    private static void set(Object value,String name,Object next)throws Exception{Field field=value.getClass().getDeclaredField(name);field.setAccessible(true);field.set(value,next);}
    private static void invoke(Object value,String name)throws Exception{invoke(value,name,new Class<?>[0]);}
    private static void invoke(Object value,String name,Class<?>[] types,Object...args)throws Exception{Method m=value.getClass().getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(value,args);}
    private static String sha(File file)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=Files.newInputStream(file.toPath())){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)digest.update(b,0,n);}StringBuilder text=new StringBuilder();for(byte b:digest.digest())text.append(String.format("%02x",b&255));return text.toString();}
